<?php require 'config.php'; $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT p.*,c.category_name FROM products p LEFT JOIN categories c ON p.category_id=c.category_id WHERE p.product_id=?');$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Không tìm thấy sản phẩm. <a href="products.php">Quay lại</a>');}$pageTitle=$p['product_name'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$qty=max(1,(int)($_POST['quantity']??1));if($p['quantity']<1)$msg='Sản phẩm đã hết hàng.';elseif($qty>$p['quantity'])$msg='Số lượng vượt quá tồn kho.';else{$_SESSION['cart'][$id]=min($p['quantity'],($_SESSION['cart'][$id]??0)+$qty);header('Location: cart.php');exit;}}require 'includes/header.php';?><div class="row g-4"><div class="col-md-6"><img class="img-fluid rounded-4 w-100" style="max-height:480px;object-fit:cover" src="<?= e($p['image'] ?: 'https://placehold.co/800x600?text=GameGear') ?>" alt="<?= e($p['product_name']) ?>"></div><div class="col-md-6"><div class="small-muted mb-2"><?= e($p['category_name']??'Phụ kiện') ?></div><h1><?= e($p['product_name']) ?></h1><p class="price fs-3"><?= money($p['price']) ?></p><p><?= nl2br(e($p['description'])) ?></p><p>Số lượng còn: <strong><?= (int)$p['quantity'] ?></strong></p><?php if($msg): ?><div class="alert alert-warning"><?= e($msg) ?></div><?php endif; ?><form method="post" class="d-flex gap-2"><input type="number" class="form-control" style="max-width:110px" name="quantity" min="1" max="<?= (int)$p['quantity'] ?>" value="1"><button class="btn btn-red" <?= $p['quantity']<1?'disabled':'' ?>>Thêm vào giỏ hàng</button></form></div></div><?php require 'includes/footer.php';?>
